import React from 'react';

import { useNavigate } from 'react-router-dom';

import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import PageHeader from '@components/PageHeader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import 'leaflet/dist/leaflet.css';
import '@raruto/leaflet-elevation/dist/leaflet-elevation.min';
import '@raruto/leaflet-elevation/dist/leaflet-elevation.min.css';

import { AuthContext } from '../../../contexts/AuthContext';
import { getWorkouts, renameWorkoutGroup } from '../@services/workouts.service';
import { IWorkout } from '../@types/workouts.types';
import WorkoutTypeIcon from '../components/WorkoutTypeIcon';
import WorkoutListItem from '../WorkoutListItem';

interface IWorkoutGroupProps {
  id_group: number;
}

const WorkoutGroup: React.FC<IWorkoutGroupProps> = ({ id_group }) => {
  const [data, setData] = React.useState<IWorkout[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error | null>(null);
  const navigate = useNavigate();
  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      getWorkouts({ offset: 0, limit: 1000, id_group }).then(setData);
    };

    fetchData()
      .catch(setErr)
      .finally(() => setIsLoading(false));
  }, [id_group]);

  if (isLoading) {
    return (
      <div style={{ height: '400px' }} className="d-flex align-items-center justify-content-center">
        <PohLoader />
      </div>
    );
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!data[0]) {
    return <pre>{JSON.stringify(data, null, '  ')}</pre>;
  }

  return (
    <section>
      <>
        <Breadcrumb
          data={[
            { href: `/workouts`, text: 'Тренировки' },
            {
              href: `/workouts/group/${id_group}`,
              text: data?.[0]?.group?.name ?? 'Группа',
              active: true,
            },
          ]}
        />
        <PohContainer>
          <PageHeader
            title={
              <span className="d-inline-flex align-items-center">
                <WorkoutTypeIcon type={data[0].type} />
                &nbsp;
                <small className="text-muted">{data[0].type.name}</small>
                &nbsp;
                {data[0].group?.name ?? 'Группа #' + id_group}{' '}
              </span>
            }
          >
            {data.some((x) => authContext.user?.id && x.user.id === +authContext.user?.id) && (
              <PohButton
                size={ButtonSize.Small}
                variant={ButtonVariant.Light}
                onClick={async () => {
                  const newName = prompt('Название группы', data[0].group?.name ?? '') ?? '';
                  await renameWorkoutGroup(id_group, newName);
                  setData((cur) =>
                    cur.map((x) => ({ ...x, group: { id: id_group, name: newName } })),
                  );
                }}
              >
                Переименовать
              </PohButton>
            )}
          </PageHeader>

          <PohRow>
            <PohCol sm={12}>
              <PohList
                data={data.map((d) => ({
                  key: d.id,
                  content: <WorkoutListItem data={d} />,
                  action: true,
                  onClick: () => navigate(`/workouts/${d.id}`),
                }))}
              />
            </PohCol>
          </PohRow>

          <details>
            <summary>Комментарии</summary>
            <CommentsWidget
              id_workout_group={id_group}
              startText="Стать первым комментатором в этой группе :)"
            />
          </details>
        </PohContainer>
      </>
    </section>
  );
};

export default WorkoutGroup;
